<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $logs = amia_premium_agum_logs( 10 ); ?>
<div class="amia-activity-list" aria-live="polite"><?php foreach ( $logs as $log ) : ?><article class="amia-activity-item amia-card"><span class="amia-activity-dot"></span><div><strong><?php echo esc_html( $log->action ); ?></strong><p class="amia-muted"><?php echo esc_html( $log->message ); ?></p><time><?php echo esc_html( $log->created_at ); ?></time></div></article><?php endforeach; ?><?php if ( ! $logs ) : ?><div class="amia-card amia-empty-state"><?php esc_html_e( 'No recent activity.', 'amia-gallery-premium' ); ?></div><?php endif; ?></div>
